:- module(m__eu_data_protection_gdpr_art15_access_copy_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(eu_reg_2016_679_art_15_1, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1), chapeau (confirmation of processing and access to the personal data)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'The data subject shall have the right to obtain from the controller confirmation as to whether or not personal data concerning him or her are being processed, and, where that is the case, access to the personal data and the following information:']).
citation(eu_reg_2016_679_art_15_1_a, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1)(a) (purposes of the processing)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the purposes of the processing;']).
citation(eu_reg_2016_679_art_15_1_b, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1)(b) (categories of personal data concerned)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the categories of personal data concerned;']).
citation(eu_reg_2016_679_art_15_1_c, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1)(c) (recipients or categories of recipient)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the recipients or categories of recipient to whom the personal data have been or will be disclosed, in particular recipients in third countries or international organisations;']).
citation(eu_reg_2016_679_art_15_1_d, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1)(d) (storage period or the criteria used to determine it)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'where possible, the envisaged period for which the personal data will be stored, or, if not possible, the criteria used to determine that period;']).
citation(eu_reg_2016_679_art_15_1_e, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1)(e) (existence of the rights to rectification, erasure, restriction and objection)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the existence of the right to request from the controller rectification or erasure of personal data or restriction of processing of personal data concerning the data subject or to object to such processing;']).
citation(eu_reg_2016_679_art_15_1_f, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1)(f) (right to lodge a complaint with a supervisory authority)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the right to lodge a complaint with a supervisory authority;']).
citation(eu_reg_2016_679_art_15_1_g, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1)(g) (source of personal data not collected from the data subject)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'where the personal data are not collected from the data subject, any available information as to their source;']).
citation(eu_reg_2016_679_art_15_1_h, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(1)(h) (automated decision-making referred to in Art 22(1) and (4))', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'the existence of automated decision-making, including profiling, referred to in Article 22(1) and (4) and, at least in those cases, meaningful information about the logic involved, as well as the significance and the envisaged consequences of such processing for the data subject.']).
citation(eu_reg_2016_679_art_15_2, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(2) (information on Article 46 safeguards for transfers)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'Where personal data are transferred to a third country or to an international organisation, the data subject shall have the right to be informed of the appropriate safeguards pursuant to Article 46 relating to the transfer.']).
citation(eu_reg_2016_679_art_15_3, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(3) (copy of the personal data, fee for further copies, commonly used electronic form)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'The controller shall provide a copy of the personal data undergoing processing. For any further copies requested by the data subject, the controller may charge a reasonable fee based on administrative costs. Where the data subject makes the request by electronic means, and unless otherwise requested by the data subject, the information shall be provided in a commonly used electronic form.']).
citation(eu_reg_2016_679_art_15_4, [label - 'Regulation (EU) 2016/679 (GDPR) Art 15(4) (copy not to adversely affect the rights and freedoms of others)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504', verbatim - 'The right to obtain a copy referred to in paragraph 3 shall not adversely affect the rights and freedoms of others.']).
citation(article_22_automated_decision_making_statement, [label - 'Referral target: statement whether the processing includes automated decision-making, including profiling, referred to in Regulation (EU) 2016/679 Art 22(1) and (4) (outside fact; decided by the orders gdpr-data-subject-rights-automated-decision and gdpr-data-subject-rights-articles-20-to-22-decision-and-exception)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504']).
citation(article_46_safeguards_statement, [label - 'Referral target: statement whether a transfer rests on appropriate safeguards pursuant to Regulation (EU) 2016/679 Art 46 (outside fact; decided by the order gdpr-chapter-v-transfers)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504']).
